// Geography 2217: physical topics (1–5), human topics (6–10) and geographical skills.
(() => {
  const K = R2O.K, G = R2O.GEN, S = R2O.SCI, { rnd, pick, n } = K;
  const idea = S.idea, X = S.X, num = S.num, bank = S.bank, eq = S.eq, r = (x, d = 2) => K.round(x, d);
  const T = (q, opts, a, why) => ({ q, opts, a, why });
  const BOOK = ['World Regional Geography (free textbook)', 'https://open.lib.umn.edu/worldgeography/'];

  R2O.SYLS.geography.objectives.push(
    { id: 'SK', a: 10, p: 26, t: 'Geographical skills: maps, graphs, images and GIS', los: ['Cartographic skills: select, construct and interpret maps using direction, scale, symbols and a key; co-ordinates, latitude and longitude, 4 and 6 figure grid references; 16-point compass and bearings; distances and area; gradient, contour lines and spot heights; cross-sections and transects.', 'Graphical skills: construct and interpret graphs, charts and diagrams (bar graphs, climate graphs, cross-sections, dispersion graphs, line graphs, pie charts, population pyramids, scatter graphs, triangular graphs, flood hydrographs and more); identify trends and patterns.', 'GIS and image skills: interpret photographs (aerial vertical and oblique, ground level), cartoons, diagrams and satellite images; recognise bias; use GIS and know its benefits and limitations.'], kw: 'map skills grid reference scale contour compass bearing graphs hydrograph gis photographs' },
    { id: 'P3', a: 10, p: 32, t: 'Paper 3: Geographical Investigations', los: ['Two compulsory questions on geographical investigation and enquiry, with short answer and extended response items, some based on source material (1 hour 30 minutes, 60 marks, 28%).'], kw: 'paper 3 geographical investigations fieldwork enquiry hypothesis data collection' });

  R2O.addSubject({
    id: 'geography', name: 'Geography', short: 'Geography', icon: '🌏', color: '#0d9488',
    blurb: 'How our planet works, and how people live on it.',
    syl: {
      code: '2217', name: 'Cambridge O Level Geography', years: '2027, 2028 and 2029',
      url: 'https://cambridgeinternational.org/Images/718204-2027-2029-syllabus.pdf',
      areas: ['Changing river environments', 'Changing coastal environments', 'Changing ecosystems', 'Tectonic hazards', 'Climate change', 'Changing populations', 'Changing towns and cities', 'Development', 'Changing economies', 'Resource provision', 'Geographical skills'],
      papers: ['Paper 1 Physical Geography: 1 hour 45 minutes, 75 marks, 36%.', 'Paper 2 Human Geography: 1 hour 45 minutes, 75 marks, 36%.', 'Paper 3 Geographical Investigations: 1 hour 30 minutes, 60 marks, 28%.', 'Structured questions with short and extended answers, some based on source material. Geographical skills apply to every paper.'],
      suggest: ['Is glaciation on my exam?', 'Do I need case studies?', 'Explain the demographic transition model', 'Quiz me on plate boundaries', 'Do I need to know the Bradshaw model?', 'Are grid references examinable?', 'What should I revise first?'],
      formulaNote: '<p>Geography has few formulas. Know: <b>river discharge = cross-sectional area × velocity</b> (m³/s), <b>natural increase = birth rate − death rate</b>, map scale (e.g. 1 : 50 000 means 1 cm = 500 m), and <b>gradient = height difference ÷ horizontal distance</b>.</p>',
      offSyllabus: [
        { k: /glacia|glacier|ice age landform/, why: 'Glaciation is not one of the ten 2217 topics. Physical topics are rivers, coasts, ecosystems (Antarctic and tropical rainforest), tectonic hazards and climate change.' },
        { k: /desert landform|sand dune desert|arid landform/, why: 'Desert landforms are not a topic in 2217. Desertification appears only as a food-supply challenge (10.3).', obj: '10.3' },
        { k: /weather station|stevenson screen|anemometer/, why: 'Weather instruments are not a topic in 2217. Climate graphs are among the graphical skills.', obj: 'SK' },
        { k: /hot desert ecosystem|savanna|tundra|coniferous/, why: 'The two ecosystems studied are the Antarctic and the tropical rainforest (3).', obj: '3.1' },
        { k: /burgess|hoyt|urban land ?use model/, why: 'Named urban land-use models are not listed in 2217. Urban topics focus on growth, its opportunities and challenges, and management (7).', obj: '7.2' }
      ]
    },
    links: (kw) => [
      ['BBC Bitesize: GCSE Geography revision', `https://www.bbc.co.uk/bitesize/search?q=${kw}`],
      ['National Geographic Education: encyclopedia', `https://education.nationalgeographic.org/resource/resource-library?q=${kw}`],
      ['Our World in Data: real global statistics', `https://ourworldindata.org/search?q=${kw}`]
    ]
  });

  // ================= generators =================
  G.geDischarge = () => { const w = pick([4, 5, 6, 8, 10, 12]), d = pick([0.5, 1, 1.5, 2]), v = pick([0.5, 0.8, 1.2, 1.5, 2]); const A = w * d, Q = r(A * v, 3);
    return num(`<p>A river channel is ${w} m wide and ${n(d)} m deep on average, and the water flows at ${n(v)} m/s. Calculate the discharge.</p>`, Q, 'm³/s', [`cross-sectional area = width × depth = ${w} × ${n(d)} = ${n(A)} m²`, `discharge = area × velocity = ${n(A)} × ${n(v)} = <b>${n(Q)} m³/s</b> (cumecs)`], 'Discharge = cross-sectional area × velocity.'); };
  G.geNatInc = () => { const br = pick([12, 18, 25, 32, 38, 44]), dr = pick([6, 8, 9, 11, 14]); const ni = br - dr;
    if (Math.random() < .5) return num(`<p>A country has a birth rate of ${br} per 1000 and a death rate of ${dr} per 1000. What is the natural increase per 1000?</p>`, ni, 'per 1000', [`natural increase = birth rate − death rate = ${br} − ${dr} = <b>${ni} per 1000</b>`], 'Natural increase = BR − DR.');
    return num(`<p>Birth rate ${br} per 1000, death rate ${dr} per 1000. What is the natural increase as a percentage?</p>`, ni / 10, '%', [`${br} − ${dr} = ${ni} per 1000`, `÷ 10 for a percentage: <b>${n(ni / 10)}%</b>`], 'Per 1000 → per 100: divide by 10.'); };
  G.geDependency = () => { const young = pick([20, 25, 30, 40]), old = pick([5, 10, 15, 20, 25]), work = 100 - young - old; const dr = (young + old) / work * 100;
    return Object.assign(num(`<p>In a country, ${young}% of people are aged 0–14, ${work}% are 15–64 and ${old}% are 65+. Calculate the dependency ratio (dependents per 100 people of working age).</p>`, 0, '', [`dependents = ${young} + ${old} = ${young + old}`, `ratio = ${young + old} ÷ ${work} × 100 = <b>${n(K.sf(dr, 3))}</b>`], 'Dependency ratio = (young + old) ÷ working age × 100.'), K.acc3(dr)); };
  G.geScale = () => { const sc = pick([25000, 50000]), cm = pick([2, 3, 4, 5, 6, 8, 2.5, 7]); const km = cm * sc / 100000;
    return num(`<p>On a 1 : ${n(sc)} map, two places are ${n(cm)} cm apart. What is the real distance in km?</p>`, km, 'km', [`1 cm = ${n(sc)} cm = ${n(sc / 100000)} km`, `${n(cm)} × ${n(sc / 100000)} = <b>${n(km)} km</b>`], `On 1 : ${n(sc)}, 1 cm on the map = ${n(sc / 100)} m on the ground.`); };
  G.geGrid = () => { const e = rnd(10, 98), nn = rnd(10, 98), de = rnd(1, 9), dn = rnd(1, 9);
    return { kind: 'text', q: `<p>A point lies in the grid square with easting ${e} and northing ${nn}. It is ${de} tenths of the way across (east) and ${dn} tenths of the way up (north). What is its 6-figure grid reference?</p>`, a: `${e}${de}${nn}${dn}`, accept: [`${e}${de}${nn}${dn}`], ph: '6 digits', hint: 'Along the corridor, then up the stairs: eastings first, then northings, each with the tenths added.', steps: [`easting ${e} + ${de} tenths → ${e}${de}`, `northing ${nn} + ${dn} tenths → ${nn}${dn}`, `<b>${e}${de}${nn}${dn}</b>`] }; };
  G.geGradient = () => { const h1 = pick([40, 60, 80, 120]), h2 = h1 + pick([20, 40, 60, 80, 100]), d = pick([200, 400, 500, 800, 1000]); const g = (h2 - h1) / d;
    if (Math.random() < .5) return num(`<p>Spot heights of ${h1} m and ${h2} m are shown on a map. What is the difference in height?</p>`, h2 - h1, 'm', [`${h2} − ${h1} = <b>${h2 - h1} m</b>`], 'Subtract the lower height from the higher.');
    return { kind: 'text', q: `<p>The height rises from ${h1} m to ${h2} m over a horizontal distance of ${d} m. Give the gradient as a ratio 1 : x.</p>`, a: `1:${r(d / (h2 - h1), 2)}`, accept: [`1:${r(d / (h2 - h1), 2)}`], ph: 'e.g. 1:10', hint: 'Gradient = vertical rise ÷ horizontal distance; write as 1 : (distance ÷ rise).', steps: [`rise = ${h2 - h1} m, distance = ${d} m`, `${d} ÷ ${h2 - h1} = ${n(r(d / (h2 - h1), 2))} → <b>1 : ${n(r(d / (h2 - h1), 2))}</b>`] }; };
  const B = (id, items) => bank(id, items.map(([q, a, w, why]) => ({ q, a, w, why })));
  B('geRivers', [
    ['A river\'s discharge is…', 'the volume of water passing a point per second (m³/s)', ['its speed only', 'its width', 'the amount of sediment'], 'Discharge = cross-sectional area × velocity.'],
    ['According to the Bradshaw model, downstream the river\'s discharge…', 'increases', ['decreases', 'stays the same', 'drops to zero'], 'Width, depth, velocity and discharge increase downstream; load particle size and channel bed roughness decrease, as does gradient.'],
    ['Hydraulic action is erosion by…', 'the force of the water itself, compressing air in cracks', ['rocks scraping the bed', 'rocks knocking into each other', 'chemicals dissolving rock'], 'Abrasion: scraping. Attrition: rocks colliding and rounding. Solution: dissolving.'],
    ['Saltation is…', 'small pebbles bouncing along the river bed', ['large boulders rolled along', 'fine particles carried in the water', 'dissolved minerals'], 'Traction: rolling. Suspension: carried. Solution: dissolved.'],
    ['Infiltration is…', 'water soaking into the soil', ['water flowing over the surface', 'water evaporating', 'rain caught by leaves'], 'Percolation is water moving deeper into rock.'],
    ['A waterfall forms where…', 'hard rock lies over softer rock, which is eroded faster', ['the river is widest', 'the river meets the sea', 'two tributaries meet'], 'An overhang forms, collapses and the waterfall retreats, leaving a gorge.'],
    ['An oxbow lake forms when…', 'a meander neck is cut through, usually in a flood, and the old loop is sealed off by deposition', ['a waterfall retreats', 'a delta grows', 'a river dries up'], 'Erosion on the outer bends narrows the neck.'],
    ['On a meander, erosion is greatest on the…', 'outside bend, where the water flows fastest', ['inside bend', 'straight sections', 'river mouth'], 'Deposition on the inside bend forms a slip-off slope.'],
    ['Levées are formed by…', 'deposition of sediment on the banks during floods', ['erosion of the river bed', 'people building walls only', 'waterfalls retreating'], 'The heaviest material is dropped first, nearest the channel.'],
    ['Which is a human cause of flooding?', 'Urbanisation (impermeable surfaces)', ['Heavy rainfall', 'Snowmelt', 'Steep slopes'], 'Also deforestation. Natural causes: heavy or prolonged rain, snowmelt, saturated ground.'],
    ['Which is a soft engineering flood strategy?', 'Planting trees in the drainage basin (afforestation)', ['Building a dam', 'Concrete embankments', 'Straightening the channel'], 'Soft engineering works with nature and is often more sustainable.'],
    ['A cause of river pollution is…', 'untreated sewage and fertiliser run-off', ['heavy rainfall alone', 'meanders', 'deltas forming'], 'Also industrial waste. Impacts: eutrophication, disease, loss of wildlife.'],
    ['A tributary is…', 'a smaller river that joins a larger one', ['the end of a river', 'a waterfall', 'a type of erosion'], 'The point where they meet is the confluence.'],
    ['The watershed is…', 'the high ground that separates two drainage basins', ['the place where a river meets the sea', 'a lake behind a dam', 'the bed of the river'], 'Rain falling on each side flows into a different river.'],
    ['V-shaped valleys form in the upper course because…', 'the river erodes downwards and the valley sides are weathered and slide down', ['the river deposits a lot of sediment', 'the sea erodes the land', 'the river is very wide'], 'Vertical erosion is strongest in the upper course.'],
    ['A delta forms where…', 'a river deposits sediment at its mouth faster than the sea can remove it', ['a river flows over hard rock', 'two rivers meet', 'a meander is cut off'], 'Examples: the Nile and Ganges–Brahmaputra deltas.'],
    ['On a flood hydrograph, the lag time is…', 'the time between the peak rainfall and the peak discharge', ['the total rainfall', 'the time the river is dry', 'the height of the river bank'], 'A short lag time means a higher flood risk.']
  ]);
  B('geCoasts', [
    ['Destructive waves…', 'are tall and frequent with a strong backwash, eroding beaches', ['are low with a strong swash, building beaches', 'only occur on calm days', 'never erode'], 'Constructive waves have a strong swash and build up beaches.'],
    ['Longshore drift moves sediment…', 'along the coast in the direction of the prevailing wind', ['straight out to sea', 'only up the beach', 'into caves'], 'Swash goes up at an angle; backwash comes straight down.'],
    ['The order of erosion on a headland is…', 'crack → cave → arch → stack → stump', ['stack → arch → cave', 'arch → crack → stump', 'cave → stump → stack'], 'Erosion widens weaknesses until the arch roof collapses.'],
    ['Headlands and bays form on a…', 'discordant coastline (alternating hard and soft rock at right angles to the coast)', ['concordant coastline', 'river delta', 'volcanic island only'], 'Soft rock erodes into bays; hard rock remains as headlands.'],
    ['A spit forms when…', 'longshore drift deposits sediment where the coast changes direction', ['waves erode a headland', 'a river floods', 'coral grows'], 'It may have a hooked end.'],
    ['Which is HARD engineering?', 'A sea wall', ['Beach nourishment', 'Managed retreat', 'Dune regeneration'], 'Hard engineering uses structures; soft engineering works with natural processes.'],
    ['Tropical storms form over…', 'warm oceans (about 27 °C or more) between about 5° and 30° of latitude', ['cold oceans near the poles', 'deserts', 'mountains'], 'Called hurricanes, cyclones or typhoons depending on location.'],
    ['Coral reefs are important because they…', 'protect coasts from waves and support huge biodiversity, fishing and tourism', ['cause tropical storms', 'produce oil', 'stop longshore drift everywhere'], 'Threats: warming (bleaching), pollution, overfishing, tourism.'],
    ['Mangroves help coasts by…', 'absorbing wave energy and trapping sediment', ['increasing erosion', 'causing storms', 'removing all fish'], 'They are also nurseries for fish.'],
    ['Constructive waves…', 'are low and gentle, with a strong swash that builds up beaches', ['are tall with a strong backwash', 'only erode cliffs', 'happen only in storms'], 'Destructive waves have a strong backwash.'],
    ['A wave-cut platform is…', 'a flat rocky area left at the foot of a cliff as the cliff retreats', ['a sandy beach', 'a sea wall', 'a type of spit'], 'Waves erode a notch, the cliff above collapses, and the cliff moves back.'],
    ['Beach nourishment means…', 'adding sand or shingle to a beach to make it wider', ['building a concrete wall', 'removing the beach', 'planting coral'], 'Soft engineering. It must be repeated as sand is washed away.'],
    ['Groynes are built to…', 'trap sand moved by longshore drift and keep the beach wide', ['make waves bigger', 'stop rivers flooding', 'create caves'], 'Hard engineering. Beaches further along can lose sand.'],
    ['Managed retreat means…', 'allowing the sea to flood some low-value land in a controlled way', ['building higher sea walls', 'pumping the sea away', 'adding sand to beaches'], 'It can create salt marshes that protect the land behind.'],
    ['A storm surge is…', 'a rise in sea level caused by low pressure and strong winds pushing water onto the coast', ['a small wave on a calm day', 'a river flood', 'an earthquake under the sea'], 'It causes much of the flooding in tropical storms.'],
    ['Coral bleaching is mainly caused by…', 'sea water becoming too warm', ['too many fish', 'cold winters', 'too much sand'], 'Stressed corals lose the algae that give them colour and food.']
  ]);
  B('geEco', [
    ['The tropical rainforest has…', 'high temperatures and heavy rainfall all year (convectional rain)', ['cold winters', 'very little rain', 'four distinct seasons'], 'Low pressure and the overhead sun near the equator.'],
    ['The layers of the rainforest from top to bottom are…', 'emergent, canopy, under-canopy (understorey), shrub layer, forest floor', ['forest floor, canopy, emergent', 'canopy, roots, emergent', 'shrub, emergent, canopy'], 'Each layer has its own light level and species.'],
    ['Buttress roots in the rainforest…', 'support very tall trees in shallow soil', ['store water for the dry season', 'catch insects', 'make the trees shorter'], 'Drip-tip leaves shed heavy rain.'],
    ['A major threat to tropical rainforests is…', 'deforestation for cattle ranching, logging, mining and farming', ['too much snow', 'tropical storms only', 'too many emergent trees'], 'Impacts: loss of biodiversity, climate change, soil erosion, loss of indigenous ways of life.'],
    ['Antarctica has a…', 'cold, dry climate with high pressure and low sun angle', ['hot, wet climate', 'low pressure and heavy rain', 'tropical climate'], 'It is technically a desert because precipitation is so low.'],
    ['Penguins survive in Antarctica by…', 'thick fat (blubber), dense feathers and huddling', ['hibernating in trees', 'sweating', 'migrating to the rainforest'], 'Adaptations to extreme cold.'],
    ['The Antarctic Treaty helps manage Antarctica by…', 'banning mining and military activity and protecting it for science', ['allowing unlimited fishing', 'opening it for oil drilling', 'building cities'], 'Other strategies: tourism rules, fishing quotas.'],
    ['Sustainable rainforest management includes…', 'selective logging and replanting, ecotourism and protected areas', ['clear-felling everything', 'more cattle ranching', 'burning for farmland'], 'Meeting today\'s needs without harming future generations.']
  ]);
  B('geTectonics', [
    ['The Earth\'s layers from the centre out are…', 'inner core, outer core, mantle, crust', ['crust, mantle, core, lithosphere', 'mantle, inner core, crust', 'outer core, crust, mantle'], 'The lithosphere is the crust plus the rigid upper mantle.'],
    ['At a constructive (divergent) boundary…', 'plates move apart and magma rises, forming new crust', ['plates collide', 'plates slide past each other', 'nothing happens'], 'e.g. the Mid-Atlantic Ridge: gentle shield volcanoes.'],
    ['At a destructive (convergent) boundary…', 'dense oceanic crust subducts under continental crust, causing violent volcanoes and earthquakes', ['plates move apart', 'no earthquakes occur', 'new crust always forms'], 'e.g. the Andes.'],
    ['At a conservative (transform) boundary…', 'plates slide past each other, causing earthquakes but no volcanoes', ['magma rises', 'mountains form by collision', 'plates move apart'], 'e.g. the San Andreas Fault.'],
    ['The focus of an earthquake is…', 'the point underground where it starts', ['the point on the surface above it', 'the strongest shaking point always', 'a type of volcano'], 'The epicentre is directly above the focus, on the surface.'],
    ['A shield volcano has…', 'gentle slopes from runny lava', ['steep sides from explosive eruptions', 'no lava at all', 'only ash'], 'Strato-volcanoes (composite cones) are steep with layers of ash and lava.'],
    ['A dormant volcano is one that…', 'has not erupted recently but could again', ['is erupting now', 'will never erupt again', 'is under the sea only'], 'Active: erupted recently. Extinct: will not erupt again.'],
    ['A lahar is…', 'a volcanic mudflow', ['a type of lava', 'a gas cloud', 'an earthquake wave'], 'Pyroclastic flows are fast, very hot clouds of gas and rock.'],
    ['Why do people live near volcanoes?', 'Fertile soil, geothermal energy, minerals and tourism', ['Because volcanoes are cold', 'There is never any danger', 'Volcanoes stop earthquakes'], 'Also family ties and lack of choice.'],
    ['Each whole number on the moment magnitude (or Richter) scale represents…', 'about 32 times more energy than the one below', ['the same energy', 'twice the energy', '100 times less energy'], 'And 10 times more ground shaking (amplitude). Mercalli measures observed effects.'],
    ['A secondary effect of an earthquake is…', 'a tsunami, fires or disease after the shaking', ['the ground shaking', 'buildings collapsing during the quake', 'the focus'], 'Primary effects happen immediately.'],
    ['Which reduces earthquake damage?', 'Earthquake-resistant buildings and drills', ['Building taller unreinforced towers', 'Ignoring warnings', 'Building on loose soil'], 'Monitoring, prediction, protection and planning.']
  ]);
  B('geClimate', [
    ['Evidence of climate change includes…', 'temperature records, ice cores, shrinking sea ice, and historic writing and paintings', ['weather forecasts for tomorrow', 'one cold day', 'the size of plates'], 'Ice cores trap ancient air.'],
    ['A natural cause of climate change is…', 'orbital changes (Milankovitch cycles), sunspots or volcanic activity', ['burning fossil fuels', 'deforestation', 'farming'], 'Human causes enhance the greenhouse effect.'],
    ['The enhanced greenhouse effect is caused by…', 'extra greenhouse gases from human activities trapping more heat', ['the hole in the ozone layer', 'more sunlight', 'earthquakes'], 'Fossil fuels, deforestation and agriculture.'],
    ['Mitigation means…', 'reducing the causes of climate change (e.g. cutting emissions)', ['adapting to its effects', 'ignoring it', 'measuring it'], 'Adaptation means coping with the effects (e.g. sea walls, drought-resistant crops).'],
    ['Which is an adaptation strategy?', 'Building flood defences', ['Switching to solar power', 'Planting forests to absorb CO₂', 'Carbon taxes'], 'The others are mitigation.'],
    ['An impact of climate change is…', 'rising sea levels flooding low-lying coasts', ['fewer extreme weather events everywhere', 'cooler oceans', 'larger ice sheets'], 'Also changing weather patterns and food production.'],
    ['The Paris Agreement aims to…', 'limit global warming to well below 2 °C', ['stop all earthquakes', 'increase coal use', 'ban all cars immediately'], 'An international mitigation agreement.']
  ]);
  B('gePopulation', [
    ['In stage 2 of the demographic transition model…', 'death rates fall rapidly while birth rates stay high, so population grows fast', ['birth and death rates are both low', 'birth rates rise', 'the population falls'], 'Better healthcare, food and water.'],
    ['A population pyramid with a wide base shows…', 'a youthful population with high birth rates', ['an ageing population', 'low birth rates', 'no children'], 'A narrow base and wide top shows an ageing population.'],
    ['A problem of an ageing population is…', 'fewer workers paying taxes to support pensions and healthcare', ['too many schools needed', 'rapid birth rate growth', 'too much unemployment of children'], 'Youthful populations need schools and jobs.'],
    ['An anti-natalist policy aims to…', 'reduce the birth rate', ['increase the birth rate', 'stop immigration', 'raise the death rate'], 'e.g. China\'s former one-child policy. Pro-natalist policies encourage births.'],
    ['A refugee is…', 'someone forced to leave their country due to war, persecution or disaster', ['someone who moves for a better job', 'a tourist', 'someone moving within their country'], 'An asylum seeker has applied for refugee status; an economic migrant moves for work.'],
    ['Which is a PULL factor?', 'Better job opportunities in the destination', ['War at home', 'Drought at home', 'Lack of healthcare at home'], 'Push factors drive people away; pull factors attract them.'],
    ['A benefit of emigration for the country of origin is…', 'money sent home by migrants (remittances)', ['losing skilled workers', 'an ageing population', 'fewer workers'], 'A downside is a "brain drain".'],
    ['Natural increase is…', 'birth rate minus death rate', ['immigration minus emigration', 'birth rate plus death rate', 'total population'], 'Net migration is the other driver of change.']
  ]);
  B('geUrban', [
    ['Urban growth is fastest today in…', 'low-income countries (LICs)', ['high-income countries', 'Antarctica', 'rural areas only'], 'Rural-to-urban migration and natural increase.'],
    ['A cause of rural-to-urban migration is…', 'more jobs and services in cities', ['better farming jobs in cities', 'cheaper land in cities', 'cities being quieter'], 'Push factors in rural areas: drought, poverty, lack of services.'],
    ['Unplanned settlements (slums) form because…', 'cities grow faster than affordable housing can be built', ['people prefer them', 'governments build them on purpose', 'they are near the coast'], 'Challenges: poor sanitation, overcrowding, insecure land rights.'],
    ['Urban sprawl means…', 'the city spreading outwards into the countryside', ['the city centre getting taller', 'people leaving cities', 'building on rivers only'], 'It pressures the rural-urban fringe.'],
    ['A sustainable urban strategy is…', 'improving public transport and self-help housing schemes', ['building more motorways only', 'bulldozing all slums with no rehousing', 'increasing waste dumping'], 'Social, economic and environmental benefits.']
  ]);
  B('geDevelopment', [
    ['GNI per capita measures…', 'the average income per person in a country', ['life expectancy', 'literacy rate', 'happiness'], 'Economic indicator. Social indicators: life expectancy, literacy, infant mortality.'],
    ['The Human Development Index (HDI) combines…', 'life expectancy, education and income', ['only income', 'only population', 'only GDP'], 'A composite indicator is more balanced than one measure.'],
    ['A reason some countries are less developed is…', 'a history of colonialism, debt, conflict or few natural resources', ['they have no people', 'they are near the sea', 'they are always cold'], 'Social, economic and environmental factors combine.'],
    ['Sustainable development means…', 'meeting present needs without compromising future generations\' needs', ['growing as fast as possible', 'using all resources now', 'stopping all development'], 'Brundtland definition.'],
    ['A disadvantage of international aid is…', 'it may not reach those who need it and can create dependency', ['it always solves poverty', 'it is never used for emergencies', 'it has no costs'], 'Fair trade and debt relief are other strategies.'],
    ['Quality of life is about…', 'well-being: health, safety, freedom, environment, not just money', ['only income', 'only the number of cars', 'GDP alone'], 'Standard of living focuses on material wealth.']
  ]);
  B('geEconomy', [
    ['Mining is a…', 'primary industry', ['secondary industry', 'tertiary industry', 'quaternary industry'], 'Primary: raw materials. Secondary: manufacturing. Tertiary: services. Quaternary: research and IT.'],
    ['As countries develop, employment usually shifts from…', 'primary to secondary to tertiary industries', ['tertiary to primary', 'quaternary to primary', 'secondary to primary'], 'HICs have most people in tertiary and quaternary jobs.'],
    ['A transnational corporation (TNC) is…', 'a company operating in more than one country', ['a local shop', 'a government department', 'a type of farm'], 'Often headquarters in an HIC, factories in LICs/MICs.'],
    ['A benefit of a TNC for a host country is…', 'jobs, skills and investment', ['profits always staying in the host country', 'no environmental impact ever', 'higher wages than anywhere else always'], 'Drawbacks: profits leave, low wages, pollution.'],
    ['Globalisation is…', 'the increasing interconnection of the world through trade, travel, communication and culture', ['countries becoming isolated', 'only about the internet', 'the end of trade'], 'Driven by transport and technology.'],
    ['The Butler model describes…', 'how a tourist resort grows, peaks, then stagnates, declines or rejuvenates', ['population growth', 'earthquake strength', 'river discharge'], 'Strengths and limitations should be evaluated.'],
    ['Ecotourism aims to…', 'protect the environment and benefit local people', ['build as many hotels as possible', 'attract the largest crowds', 'ignore local culture'], 'A sustainable tourism strategy.']
  ]);
  B('geResources', [
    ['Subsistence farming produces…', 'food mainly for the farmer\'s own family', ['crops for export', 'only meat', 'food for supermarkets'], 'Commercial farming sells for profit.'],
    ['Hydroponics is…', 'growing plants in nutrient-rich water without soil', ['farming fish in rivers', 'irrigating deserts', 'keeping animals'], 'Aquaponics combines fish farming and hydroponics.'],
    ['Food insecurity means…', 'not having reliable access to enough affordable, nutritious food', ['having too much food', 'farming in cities', 'only eating rice'], 'Causes: drought, conflict, poverty, pests, climate change.'],
    ['Desertification can be managed by…', 'planting trees, terracing and stone lines (bunds) to hold water and soil', ['removing all vegetation', 'more overgrazing', 'burning crops'], 'Sustainable approaches restore the land.'],
    ['Energy security means…', 'having reliable, affordable access to energy', ['using only coal', 'exporting all energy', 'having no power stations'], 'Energy deficit countries must import.'],
    ['Which energy source is renewable?', 'Geothermal', ['Coal', 'Natural gas', 'Nuclear'], 'Also biomass, HEP, solar, tidal, wave, wind.'],
    ['A disadvantage of hydroelectric power is…', 'dams flood land, displacing people and habitats', ['it releases lots of CO₂ while running', 'it runs out quickly', 'it cannot be stored'], 'Advantages: renewable, reliable, low emissions.'],
    ['Why is energy demand rising globally?', 'Population growth and economic development', ['Fewer people are using electricity', 'Countries are becoming poorer', 'Technology uses less energy'], 'Especially in MICs.']
  ]);
  B('geSkills', [
    ['When giving a grid reference, you give…', 'the easting (along) first, then the northing (up)', ['the northing first', 'the height first', 'only one number'], '"Along the corridor, then up the stairs."'],
    ['Contour lines close together show…', 'a steep slope', ['a gentle slope', 'flat land', 'a river'], 'Far apart = gentle slope.'],
    ['On a 1 : 50 000 map, 1 cm represents…', '500 m', ['50 m', '5 km', '50 km'], '50 000 cm = 500 m.'],
    ['Which graph best shows a country\'s age and sex structure?', 'A population pyramid', ['A pie chart', 'A climate graph', 'A rose chart'], 'Bars for each age group, males and females.'],
    ['A flood hydrograph shows…', 'rainfall and river discharge over time', ['the shape of a river channel', 'the age of a population', 'plate movements'], 'Lag time = time between peak rainfall and peak discharge.'],
    ['A choropleth map shows data using…', 'different shading for areas', ['arrows of different widths', 'dots for each item', 'lines joining equal values'], 'Flow line maps use arrows; isolines join equal values.'],
    ['A good hypothesis for fieldwork is…', 'a testable statement, e.g. "River velocity increases downstream"', ['a question with no answer', 'a list of equipment', 'a conclusion written first'], 'Collect data, present it, analyse, conclude and evaluate.'],
    ['A limitation of GIS is…', 'it can be expensive and the data may be out of date or inaccurate', ['it can never show patterns', 'it cannot show maps', 'it only works on paper'], 'Benefits: layers of data, quick analysis.']
  ]);

  // ================= lessons =================
  const L = (id, title, obj, kw, hook, scenes, keys, gens, easy) => ({ id, title, obj, kw, hook, scenes, keys, gens, easy: easy || [gens[gens.length - 1]], learn: [] });
  R2O.addModule({ subject: 'geography', id: 'ge-phys', name: 'Physical geography', icon: '🏔️', color: '#0d9488', book: BOOK,
    blurb: 'Paper 1: rivers, coasts, ecosystems, tectonic hazards and climate change.',
    lessons: [
      L('ge-rivers', 'Rivers and drainage basins', ['1.1', '1.2'], 'rivers drainage basin erosion transportation landforms meanders waterfalls', 'Every river starts as a raindrop. Here is the journey.', [
        { say: idea('A <b>drainage basin</b> is the area of land that funnels rain into one river. Rain either soaks in (<b>infiltration</b>) or runs over the surface. In the river, moving water <b>erodes</b>, <b>carries</b> and <b>drops</b> material, and those three processes carve every river landform.') },
        { say: 'Make it rain on a drainage basin.', anim: X([{ k: 'r', label: 'Rain intensity', min: 1, max: 10, v: 5 }, { k: 's', label: 'Surface', min: 0, max: 2, v: 0, fmt: i => ['forest', 'farmland', 'concrete city'][i] }], v => { const inf = [0.8, 0.55, 0.15][v.s], cap = 6 - v.s * 2; const soak = Math.min(v.r * inf, cap), over = r(v.r - soak, 1); return `<p class="center bigq">🌧️ ${v.r} → 💧 soaks in ${r(soak, 1)} · 🌊 runs off ${over}</p><div class="xbar"><div style="width:${over * 10}%"></div></div><p class="center small muted">More overland flow → water reaches the river faster → higher flood risk.</p>`; }) },
        { say: 'Downstream, the river changes (the <b>Bradshaw model</b>): width, depth, velocity and discharge <b>increase</b>; gradient, bed roughness and particle size <b>decrease</b>.', ask: T('Erosion by rocks scraping the river bed is…', ['abrasion', 'attrition', 'solution', 'hydraulic action'], 0, 'Attrition: rocks knock together and get smaller and rounder.') },
        { say: 'Watch a meander become an oxbow lake.', anim: X([{ k: 't', label: 'Time', min: 0, max: 3, v: 0, fmt: i => ['young meander', 'neck narrows', 'flood cuts through', 'oxbow lake'][i] }], v => `<p class="center bigq">${['〰️ gentle bend', '➰ erosion on the outer bends', '🌊 the river takes the shortcut', '🔵 the old loop is sealed off by deposition'][v.t]}</p><p class="center small muted">Fastest water on the outside bend erodes (river cliff); slow water on the inside deposits (slip-off slope).</p>`) }
      ], ['Drainage basin terms and processes (precipitation, interception, infiltration, percolation, flows, evapotranspiration).', 'Erosion: hydraulic action, abrasion, attrition, solution. Transport: traction, saltation, suspension, solution.', 'Bradshaw model.', 'Landforms: waterfalls, gorges, rapids, V-shaped valleys, interlocking spurs, potholes, meanders, oxbow lakes, levées, floodplains, deltas.'], ['geDischarge', 'geRivers'], ['geRivers']),
      L('ge-floods', 'Floods and river pollution', ['1.3'], 'river flooding causes impacts management pollution hydrograph', 'Rivers give life, and sometimes take it.', [
        { say: idea('Living by a river gives water, fertile soil, transport and power, but also <b>flood</b> and <b>pollution</b> risks. Floods happen when water reaches the river <b>faster</b> than the channel can carry it away. Many human actions speed that water up.') },
        { say: 'Turn a farmland basin into a city. Watch the flood hydrograph.', anim: X([{ k: 'u', label: 'Urbanisation', min: 0, max: 10, v: 2 }], v => { const lag = 12 - v.u * 0.8, peak = 3 + v.u * 0.5; return `${K.plot([{ f: x => 1 + (peak - 1) * Math.exp(-((x - (6 + lag)) ** 2) / (6 - v.u * .35)) }], [], { xmin: 0, xmax: 30, ymin: 0, ymax: 9, h: 180, gstep: 1e9, lstep: 1e9, xlab: 'hours', ylab: 'discharge' })}<p class="center">lag time ≈ <b>${n(r(lag, 1))} h</b> · peak ≈ <b>${n(r(peak, 1))}</b></p><p class="center small muted">Concrete and drains: shorter lag time, higher peak → more flooding.</p>`; }) },
        { say: 'Managing floods:', pic: '<p><b>Hard engineering</b>: dams, embankments, channel straightening, flood walls (expensive, can move the problem downstream).</p><p><b>Soft engineering</b>: afforestation, floodplain zoning, wetlands, warnings (cheaper, more sustainable, slower to work).</p>', ask: T('Which is a NATURAL cause of flooding?', ['Prolonged heavy rain on saturated ground', 'Building car parks', 'Cutting down trees'], 0, 'Human causes increase run-off speed.') },
        { say: 'Pollution: sewage, factory waste and fertiliser run-off cause disease, fish deaths and eutrophication. Managed by treatment works, laws and buffer strips. Learn one named example each for a flood and for river pollution.' }
      ], ['Opportunities and hazards of living by rivers.', 'Natural and human causes of floods; impacts; hydrographs.', 'Hard vs soft flood management (evaluate; sustainable).', 'River pollution causes, impacts, management. Two named case studies.'], ['geRivers']),
      L('ge-coasts', 'Coastal processes and landforms', ['2.1', '2.2'], 'coastal erosion longshore drift waves headlands bays caves arches stacks spits', 'The sea sculpts cliffs into arches and towers over centuries.', [
        { say: idea('Waves carry energy from the wind. <b>Destructive</b> waves pull material away (erosion); <b>constructive</b> waves push it up the beach (deposition). Where rock is weak, the sea attacks faster, so the coast\'s shape depends on <b>which rocks</b> meet the sea and <b>how</b>.') },
        { say: 'Erode a headland.', anim: X([{ k: 't', label: 'Centuries pass', min: 0, max: 4, v: 0, fmt: i => ['crack', 'cave', 'arch', 'stack', 'stump'][i] }], v => `<p class="center bigq">${['🪨 a crack in the headland', '🕳️ hydraulic action widens it into a cave', '🌉 caves on both sides meet: an arch', '🗿 the arch roof collapses: a stack', '🪨 the stack is worn down: a stump'][v.t]}</p>`) },
        { say: 'Longshore drift: waves hit the beach at an angle (swash), then drain straight back (backwash), so sediment zigzags <b>along</b> the coast. Where the coast bends, it builds a <b>spit</b>; across a bay, a <b>bar</b>.', ask: T('Headlands and bays form on a coastline where…', ['bands of hard and soft rock meet the sea at right angles (discordant)', 'the rock is all the same', 'there are no waves'], 0, 'Soft rock is eroded back into bays.') }
      ], ['Erosion processes: hydraulic action, corrasion (abrasion), corrosion (solution), attrition; transport; deposition; longshore drift.', 'Constructive vs destructive waves; wave refraction.', 'Landforms: headlands, bays, cliffs, wave-cut platforms, caves, arches, stacks, stumps, beaches, spits, bars, dunes.', 'Discordant vs concordant coasts.'], ['geCoasts']),
      L('ge-coasthaz', 'Coastal hazards, storms and reefs', ['2.3'], 'coastal management tropical storms coral reefs mangroves', 'Defending the coast, and the natural defences we are losing.', [
        { say: idea('Coasts offer trade, fishing, tourism and flat land, but face <b>erosion</b>, <b>flooding</b> and <b>tropical storms</b>. People defend them with <b>hard engineering</b> (concrete) or <b>soft engineering</b> (working with nature). <b>Coral reefs</b> and <b>mangroves</b> are natural sea defences that also support life.') },
        { say: 'Compare defences.', anim: X([{ k: 'd', label: 'Defence', min: 0, max: 4, v: 0, fmt: i => ['sea wall', 'groynes', 'rock armour', 'beach nourishment', 'managed retreat'][i] }], v => { const d = [['hard', 'reflects waves; very effective but expensive and ugly'], ['hard', 'traps longshore drift to build the beach, but starves beaches further along'], ['hard', 'big boulders absorb wave energy; cheaper'], ['soft', 'adds sand to widen the beach; natural look, must be repeated'], ['soft', 'lets low-value land flood to create marsh; cheap, but land is lost']][v.d]; return `<p class="center bigq">${['🧱', '🪵', '🪨', '🏖️', '🌾'][v.d]} ${d[0]} engineering</p><p class="center">${d[1]}</p>`; }) },
        { say: 'Tropical storms (hurricanes, cyclones, typhoons) form over warm oceans and bring strong winds, storm surges and flooding. Managed by <b>prediction, preparation, planning and protection</b>.', ask: T('Why are mangroves valuable?', ['They absorb wave energy, trap sediment and shelter young fish', 'They cause storms', 'They increase erosion'], 0, 'Threatened by clearing for farms and shrimp ponds.') },
        { say: 'Learn one named coastal area (erosion and its management) and one named coral reef (importance, threats, management).' }
      ], ['Opportunities and hazards of coasts.', 'Hard and soft engineering: evaluate; sustainable.', 'Tropical storms: distribution, impacts, management.', 'Coral reefs and mangroves: importance, threats, protection. Two case studies.'], ['geCoasts']),
      L('ge-ecosystems', 'Rainforests and Antarctica', ['3.1', '3.2', '3.3', '3.4'], 'tropical rainforest antarctic ecosystem adaptations threats management', 'Two extremes: the hottest, wettest forests and the coldest continent.', [
        { say: idea('An <b>ecosystem</b> is living things (<b>biotic</b>) interacting with their environment (<b>abiotic</b>: climate, soil, water). Climate sets the rules, and plants and animals <b>adapt</b> to survive them. Rainforests and Antarctica are opposites that teach the same idea.') },
        { say: 'Switch between the two.', anim: X([{ k: 'e', label: 'Ecosystem', min: 0, max: 1, v: 0, fmt: i => ['tropical rainforest', 'Antarctic'][i] }], v => v.e ? '<p class="center bigq">🧊🐧 Antarctic</p><ul><li>High pressure, low sun angle: very cold, very dry</li><li>Adaptations: blubber, dense feathers, huddling, antifreeze proteins in fish</li><li>Threats: climate change, fishing, tourism, resource exploitation</li><li>Managed by the Antarctic Treaty, quotas, tourism rules</li></ul>' : '<p class="center bigq">🌳🦜 Tropical rainforest</p><ul><li>Near the equator: overhead sun, low pressure, convectional rain every afternoon, ~27 °C all year</li><li>Layers: emergent, canopy, understorey, shrub, forest floor</li><li>Adaptations: buttress roots, drip tips, lianas, camouflage</li><li>Threats: logging, cattle ranching, mining, roads, HEP dams</li></ul>') },
        { say: 'Destroying rainforest causes loss of biodiversity, soil erosion, more CO₂ and harm to indigenous peoples. Sustainable management: selective logging, replanting, ecotourism, protected areas, debt-for-nature swaps.', ask: T('Drip-tip leaves help rainforest plants…', ['shed heavy rain quickly', 'store water', 'catch insects'], 0, 'This stops fungi and the weight of water damaging the leaf.') }
      ], ['Location, climate, features and interrelationships of both ecosystems.', 'Adaptations of flora and fauna.', 'Threats, impacts and sustainable management (evaluate).', 'One named rainforest case study.'], ['geEco']),
      L('ge-tectonics', 'Plates, earthquakes and volcanoes', ['4.1', '4.2'], 'plate tectonics plate boundaries earthquakes volcanoes', 'The ground beneath you is a jigsaw that never stops moving.', [
        { say: idea('The Earth\'s crust is broken into <b>plates</b> floating on the hot mantle, moving a few centimetres a year. Almost all earthquakes and volcanoes happen <b>where plates meet</b>. What happens depends on whether they move <b>apart</b>, <b>together</b> or <b>past</b> each other.') },
        { say: 'Choose a plate boundary.', anim: X([{ k: 'b', label: 'Boundary', min: 0, max: 3, v: 0, fmt: i => ['constructive', 'destructive', 'collision', 'conservative'][i] }], v => `<p class="center bigq">${['⬅️ ⬆️ ➡️', '➡️ ⬇️ ⬅️', '➡️ 🏔️ ⬅️', '⬆️ ⬇️'][v.b]}</p><p class="center">${['Plates move <b>apart</b>; magma rises; gentle <b>shield volcanoes</b>, small earthquakes (e.g. Iceland).', 'Oceanic plate <b>subducts</b> under continental; melting makes explosive <b>strato-volcanoes</b> and big earthquakes (e.g. Andes, Japan).', 'Two continental plates <b>collide</b>; fold mountains, strong earthquakes, no volcanoes (e.g. Himalayas).', 'Plates <b>slide past</b>; friction builds then releases as earthquakes, no volcanoes (e.g. San Andreas).'][v.b]}</p>`) },
        { say: 'Earthquake terms: <b>focus</b> (where it starts underground), <b>epicentre</b> (directly above on the surface), <b>seismic waves</b>. Volcano terms: magma chamber, vent, crater, secondary cone. Volcanoes are active, dormant or extinct.', ask: T('Which boundary has earthquakes but NO volcanoes?', ['Conservative', 'Constructive', 'Destructive'], 0, 'No magma rises there.') }
      ], ['Layers of the Earth; plates and their movement.', 'Boundary types and where earthquakes and volcanoes occur.', 'Focus, epicentre, seismic waves; volcano types, features and classification; volcanic hazards.'], ['geTectonics']),
      L('ge-hazards', 'Living with tectonic hazards', ['4.3', '4.4'], 'earthquake impacts responses magnitude prediction', 'Why do millions choose to live next to volcanoes?', [
        { say: idea('Hazards become disasters when they meet <b>vulnerable people</b>. The same earthquake can kill hundreds in one country and very few in another, depending on <b>buildings, preparation and wealth</b>. Managing hazards means monitoring, predicting, protecting and planning.') },
        { say: 'Each step on the magnitude scale is a big jump in energy.', anim: X([{ k: 'm', label: 'Magnitude', min: 3, max: 9, v: 6 }], v => `<p class="center bigq">M${v.m}: ${n(r(Math.pow(31.6, v.m - 3), 0))} × the energy of M3</p><div class="xbar"><div style="width:${Math.min(100, (v.m - 3) * 17)}%"></div></div><p class="center small muted">Each whole number ≈ 32× more energy (10× more shaking). Mercalli measures what people observe; VEI measures eruptions.</p>`) },
        { say: 'Primary effects happen straight away (collapsing buildings); secondary effects follow (fires, tsunamis, disease, homelessness). Responses can be <b>short-term</b> (rescue, aid) or <b>long-term</b> (rebuilding, stricter building codes).', ask: T('Why do people live near volcanoes?', ['Fertile soils, geothermal energy, minerals and tourism', 'They are always safe', 'Eruptions are predictable to the minute'], 0, 'Plus family ties and lack of alternatives.') },
        { say: 'Learn one named earthquake and one named eruption: causes, impacts, responses and management.' }
      ], ['Reasons people live in hazard zones.', 'Impacts of earthquakes and eruptions; primary vs secondary.', 'Measuring: moment magnitude, Richter, Mercalli, VEI.', 'Responses and management (monitoring, prediction, protection, planning). Two case studies.'], ['geTectonics']),
      L('ge-climate', 'Climate change', ['5.1', '5.2', '5.3'], 'climate change greenhouse effect mitigation adaptation', 'The biggest geography story of your lifetime.', [
        { say: idea('Greenhouse gases act like a <b>blanket</b>: they let sunlight in but trap some of the heat trying to escape. Humans are <b>thickening the blanket</b> by burning fossil fuels, cutting forests and farming, so the planet warms. Responses either <b>cut the cause</b> (mitigation) or <b>cope with the effects</b> (adaptation).') },
        { say: 'Add carbon dioxide.', anim: X([{ k: 'c', label: 'CO₂ (ppm)', min: 280, max: 560, step: 20, v: 420 }], v => `<p class="center bigq">🌡️ about +${n(r((v.c - 280) / 280 * 3, 1))} °C warmer than pre-industrial (very rough)</p><div class="xbar"><div style="width:${(v.c - 280) / 2.8}%"></div></div><p class="center small muted">Today ≈ 420 ppm. Pre-industrial ≈ 280 ppm.</p>`) },
        { say: 'Evidence: temperature records, ice cores, shrinking sea ice, historic writing and paintings. Natural causes: Milankovitch cycles, sunspots, volcanoes. Impacts: rising seas, extreme weather, shifting farming zones.', ask: T('Building sea walls against rising seas is…', ['adaptation', 'mitigation', 'neither'], 0, 'Switching to renewables is mitigation.') },
        { say: 'Responses at every scale: international (the Paris Agreement), national (carbon taxes, renewables), local (flood defences, drought-resistant crops). Learn one named country or region case study.' }
      ], ['Evidence; natural and human causes; enhanced greenhouse effect.', 'Impacts at different scales, now and predicted.', 'Mitigation vs adaptation (evaluate); international agreements. One case study.'], ['geClimate'])
    ] });

  R2O.addModule({ subject: 'geography', id: 'ge-human', name: 'Human geography', icon: '🏙️', color: '#0369a1', book: BOOK,
    blurb: 'Paper 2: populations, migration, cities, development, economies, food and energy.',
    lessons: [
      L('ge-population', 'Population change', ['6.1', '6.2'], 'population growth demographic transition model population pyramids policies', 'From 1 billion people in 1800 to over 8 billion today. Why?', [
        { say: idea('A population grows when <b>births exceed deaths</b> (natural increase) or when more people move in than out. As countries develop, death rates fall first, then birth rates follow: the <b>demographic transition model</b>. Each stage gives the population pyramid a different shape.') },
        { say: 'Move through the DTM.', anim: X([{ k: 's', label: 'Stage', min: 1, max: 5, v: 2 }], v => { const shapes = ['🔺 very wide base, narrow top', '🔺 wide base: youthful, growing fast', '🏛️ narrowing base: growth slowing', '▮ straight sides: stable, ageing', '🔻 narrower base than middle: declining']; const br = [40, 40, 25, 12, 9][v.s - 1], dr = [40, 15, 10, 10, 11][v.s - 1]; return `<p class="center bigq">Stage ${v.s}</p><p class="center">birth rate ≈ <b>${br}</b> · death rate ≈ <b>${dr}</b> per 1000 → natural increase ${br - dr}</p><p class="center">pyramid: ${shapes[v.s - 1]}</p>`; }) },
        { say: 'Youthful populations need schools and jobs; ageing populations need pensions and care, with fewer workers paying taxes. <b>Pro-natalist</b> policies encourage births; <b>anti-natalist</b> policies discourage them.', ask: T('In which DTM stage do death rates fall fastest while birth rates stay high?', ['Stage 2', 'Stage 1', 'Stage 4', 'Stage 5'], 0, 'Medicine and clean water arrive before families shrink.') }
      ], ['Global growth patterns; birth rate, death rate, fertility rate, natural increase, migration.', 'DTM: stages, strengths, limitations.', 'Pyramids; youthful vs ageing impacts.', 'Pro- and anti-natalist policies (evaluate). One country case study.'], ['geNatInc', 'geDependency', 'gePopulation'], ['gePopulation']),
      L('ge-migration', 'International migration', ['6.3'], 'migration push pull factors refugees economic migrants', 'Why people leave home, and what happens when they arrive.', [
        { say: idea('People move when <b>push</b> factors (war, poverty, disaster) drive them out and <b>pull</b> factors (jobs, safety, family) draw them in. Migration changes <b>three</b> places: the migrant\'s life, the country they leave, and the country they reach.') },
        { say: 'Sort the factor.', anim: X([{ k: 'f', label: 'Factor', min: 0, max: 5, v: 0, fmt: i => ['war', 'better wages', 'drought', 'family already there', 'persecution', 'good schools'][i] }], v => `<p class="center bigq">${[0, 2, 4].includes(v.f) ? '⬅️ PUSH' : '➡️ PULL'}</p>`) },
        { say: 'Types: <b>economic migrant</b> (for work), <b>refugee</b> (forced out by war or persecution), <b>asylum seeker</b> (applying for refugee status). Origin countries gain remittances but lose workers (brain drain); destinations gain workers but may face pressure on services.', ask: T('Money that migrants send home is called…', ['remittances', 'aid', 'taxes'], 0, 'A major income source for many LICs.') }
      ], ['Types of migrant.', 'Push and pull factors.', 'Impacts on migrant, origin and destination.', 'Managing migration (evaluate). One named migration case study.'], ['gePopulation']),
      L('ge-urban', 'Towns and cities', ['7.1', '7.2', '7.3'], 'urbanisation urban growth slums sprawl sustainable cities', 'Half of humanity now lives in cities, and the biggest are growing fastest.', [
        { say: idea('Cities grow from two engines: <b>natural increase</b> and <b>rural-to-urban migration</b>. In low-income countries, people arrive faster than homes, water and jobs can be provided, creating both <b>opportunities</b> and serious <b>challenges</b>.') },
        { say: 'Speed up a city\'s growth.', anim: X([{ k: 'g', label: 'Growth rate', min: 1, max: 10, v: 6 }], v => `<p class="center bigq">${v.g < 4 ? '🏘️ manageable' : v.g < 7 ? '🏙️ strained services' : '🏚️ unplanned settlements spread'}</p><p class="center small muted">Fast growth → housing shortages, informal jobs, traffic, waste, pollution, and urban sprawl onto the rural-urban fringe.</p>`) },
        { say: 'Opportunities: jobs, education, healthcare, culture. Management: self-help housing, site-and-service schemes, public transport, waste recycling. Learn one named urban area.', ask: T('Which is a sustainable urban strategy?', ['Self-help housing schemes with basic services', 'Bulldozing slums with no rehousing', 'Building only motorways'], 0, 'Improves lives while involving residents.') }
      ], ['Variations in urban growth; causes of rapid growth in LICs.', 'Opportunities and challenges; unplanned settlements; urban sprawl.', 'Managing urban growth sustainably (evaluate). One case study.'], ['geUrban']),
      L('ge-development', 'Development', ['8.1', '8.2', '8.3'], 'development indicators gni hdi development gap aid sustainable development', 'Why are some countries rich and others poor? And what can change it?', [
        { say: idea('Development is about improving people\'s lives: <b>income</b>, but also <b>health, education and freedom</b>. We measure it with <b>indicators</b>. No single number tells the whole story, so composite measures like HDI combine several.') },
        { say: 'Compare two indicators.', anim: X([{ k: 'i', label: 'Indicator', min: 0, max: 3, v: 0, fmt: i => ['GNI per capita', 'life expectancy', 'literacy rate', 'HDI'][i] }], v => `<p class="center bigq">${['💵 economic: average income', '❤️ social: health', '📚 social: education', '🧮 composite: income + health + education'][v.i]}</p><p class="center small muted">${['A country can have a high average income but huge inequality.', 'Shows healthcare, diet and clean water.', 'Shows access to schooling.', 'More balanced than any one measure.'][v.i]}</p>`) },
        { say: 'The <b>development gap</b> has social, economic and environmental causes: colonial history, debt, conflict, disease, climate, landlocked location. Ways to close it: fair trade, aid, debt relief, investment, education.', ask: T('Sustainable development means…', ['meeting present needs without harming future generations', 'growing the economy as fast as possible', 'using all resources now'], 0, 'Social, economic and environmental balance.') }
      ], ['Indicators (GNP, GDP, GNI, literacy, life expectancy, HDI…); evaluate their usefulness.', 'Quality of life vs standard of living.', 'Uneven development; LICs, MICs, HICs.', 'Sustainable development; trade, aid, debt relief (evaluate). One LIC/MIC case study.'], ['geDevelopment']),
      L('ge-economy', 'Jobs, globalisation and tourism', ['9.1', '9.2', '9.3'], 'employment structure industry globalisation tnc tourism butler model', 'Your phone was designed in one country, made in another and sold everywhere.', [
        { say: idea('Jobs fall into four sectors: <b>primary</b> (raw materials), <b>secondary</b> (making things), <b>tertiary</b> (services) and <b>quaternary</b> (research, IT). As a country develops, workers shift <b>up</b> the sectors. <b>Globalisation</b> links economies through trade, transport and technology, often via <b>TNCs</b>.') },
        { say: 'Develop a country.', anim: X([{ k: 'd', label: 'Development', min: 0, max: 2, v: 0, fmt: i => ['LIC', 'MIC', 'HIC'][i] }], v => { const s = [[70, 10, 20, 0], [35, 30, 33, 2], [2, 18, 70, 10]][v.d]; return `${S.stores([['primary', s[0]], ['secondary', s[1]], ['tertiary', s[2]], ['quaternary', s[3]]], 100).replace(/ J</g, '%<')}<p class="center small muted">% of workers in each sector (illustrative)</p>`; }) },
        { say: 'Tourism grows with cheaper flights, more leisure time and the internet. The <b>Butler model</b>: exploration → involvement → development → consolidation → stagnation → decline or rejuvenation. Sustainable tourism (ecotourism) protects places and benefits local people.', ask: T('A disadvantage of a TNC for its host country is…', ['profits often go back to the home country', 'it brings jobs', 'it brings new skills'], 0, 'Evaluate both sides.') }
      ], ['Primary, secondary, tertiary, quaternary; changing employment structure.', 'Industrial location factors.', 'Globalisation; TNCs (evaluate impacts). Case study.', 'Tourism growth, Butler model, benefits and problems, sustainable management. Case study.'], ['geEconomy']),
      L('ge-food', 'Food supply', ['10.1', '10.2', '10.3'], 'farming types food supply food insecurity desertification', 'There is enough food for everyone. So why do so many go hungry?', [
        { say: idea('Farms are <b>systems</b>: inputs (land, water, seeds, labour) → processes (ploughing, harvesting) → outputs (crops, meat). Food supply depends on nature and people, and food insecurity often comes from <b>access</b> (poverty, conflict, distribution), not just total production.') },
        { say: 'Compare farming types.', anim: X([{ k: 'f', label: 'Type', min: 0, max: 3, v: 0, fmt: i => ['subsistence', 'commercial', 'hydroponics', 'aquaponics'][i] }], v => `<p class="center bigq">${['👨‍🌾 grows food for the family', '🚜 grows crops or animals to sell for profit', '💧 plants in nutrient water, no soil', '🐟🌱 fish waste feeds plants, plants clean water'][v.f]}</p>`) },
        { say: 'Challenges: drought, pests, conflict, soil erosion, desertification, climate change. Strategies: irrigation, new seed varieties, appropriate technology, food aid (helps short-term, but can create dependency).', ask: T('Which helps reduce desertification?', ['Planting trees and building stone lines to hold soil and water', 'Overgrazing', 'Removing vegetation'], 0, 'Sustainable land management.') }
      ], ['Farming types and systems.', 'Calorie intake patterns; changing production and consumption; globalisation of food.', 'Food insecurity causes and problems; food aid (evaluate); desertification and soil erosion management. Case study.'], ['geResources']),
      L('ge-energy', 'Energy', ['10.4', '10.5', '10.6'], 'energy resources renewable non-renewable energy security energy mix', 'Keeping the lights on, without wrecking the planet.', [
        { say: idea('Every country needs <b>energy security</b>: reliable, affordable energy. Demand rises with population and development. The choice of <b>energy mix</b> balances cost, reliability and environmental impact. Fossil fuels are reliable but polluting; renewables are clean but can be weather-dependent.') },
        { say: 'Build an energy mix.', anim: X([{ k: 'r', label: 'Renewables (%)', min: 0, max: 100, step: 10, v: 30 }], v => `<p class="center bigq">⚡ ${v.r}% renewable · 🏭 ${100 - v.r}% fossil/nuclear</p><p class="center">${v.r < 40 ? 'Reliable and cheap now, but high emissions and finite fuels.' : v.r < 80 ? 'Balanced: cleaner, still dependable with some backup.' : 'Very clean, but needs storage and backup for calm, dark days.'}</p>`) },
        { say: 'LICs often rely on fuelwood; HICs on a mix. Ways to increase supply: new oil and gas, HEP dams, solar farms, nuclear. Learn one named country\'s energy mix.', ask: T('A country that uses more energy than it produces has an energy…', ['deficit', 'surplus', 'security'], 0, 'It must import.') }
      ], ['Renewable vs non-renewable types.', 'Rising demand; surplus and deficit; energy security.', 'Advantages and disadvantages of sources; strategies; sustainable management. Case study.'], ['geResources'])
    ] });

  R2O.addModule({ subject: 'geography', id: 'ge-skills', name: 'Map and data skills', icon: '🗺️', color: '#65a30d', book: BOOK,
    blurb: 'Skills for all three papers: grid references, scale, contours, graphs, images, GIS and investigations.',
    lessons: [
      L('ge-maps', 'Reading maps', ['SK'], 'map skills grid references scale contours compass bearings', 'A map is a giant picture compressed onto paper. Learn to unfold it.', [
        { say: idea('Maps shrink the world by a fixed <b>scale</b>, use a <b>grid</b> so any place has an address, and show height with <b>contour lines</b>. Once you read those three things, any map makes sense.') },
        { say: 'Move a point and read its 6-figure grid reference.', anim: X([{ k: 'x', label: 'Across (tenths)', min: 0, max: 9, v: 4 }, { k: 'y', label: 'Up (tenths)', min: 0, max: 9, v: 7 }], v => `${S.svg(200, 200, `<rect x="20" y="20" width="160" height="160" fill="color-mix(in srgb, var(--c1) 8%, transparent)" stroke="var(--text)" stroke-width="2"/>${[...Array(9)].map((_, i) => `<line x1="${36 + i * 16}" y1="20" x2="${36 + i * 16}" y2="180" stroke="var(--line)"/><line x1="20" y1="${36 + i * 16}" x2="180" y2="${36 + i * 16}" stroke="var(--line)"/>`).join('')}<circle cx="${20 + v.x * 16 + 8}" cy="${180 - v.y * 16 - 8}" r="6" fill="var(--c4)"/>${S.txt(20, 196, '43', 'tick')}${S.txt(10, 184, '27', 'tick', 'end')}`, 200)}<p class="center bigq">43${v.x}27${v.y}</p><p class="center small muted">Along the corridor (easting 43 + tenths), then up the stairs (northing 27 + tenths).</p>`) },
        { say: 'Scale: on 1 : 50 000, 1 cm = 500 m; on 1 : 25 000, 1 cm = 250 m. Contours close together = steep; far apart = gentle. Directions use the 16-point compass; bearings are measured clockwise from north.', ask: T('On a 1 : 25 000 map, 4 cm is…', ['1 km', '4 km', '100 m', '25 km'], 0, '4 × 250 m = 1000 m.') }
      ], ['4- and 6-figure grid references; latitude and longitude.', 'Scale, distance and area; 16-point compass and bearings.', 'Contours, spot heights, gradient, cross-sections.', 'Map types: choropleth, flow line, isoline, topographic and more.'], ['geGrid', 'geScale', 'geGradient', 'geSkills'], ['geSkills']),
      L('ge-data', 'Graphs, images and investigations', ['SK', 'P3'], 'graphs hydrograph climate graph population pyramid gis fieldwork investigation', 'Geographers turn data into stories, then test them.', [
        { say: idea('The right graph makes a pattern jump out. Then an <b>investigation</b> tests an idea properly: a <b>hypothesis</b> → collect data → present it → analyse → conclude → evaluate what could be better.') },
        { say: 'Pick the best graph for the data.', anim: X([{ k: 'd', label: 'Data', min: 0, max: 4, v: 0, fmt: i => ['age and sex', 'rain + temperature by month', 'river flow after a storm', 'two variables', 'wind direction frequency'][i] }], v => `<p class="center bigq">${['📊 population pyramid', '🌡️ climate graph (bars + line)', '🌊 flood hydrograph', '⚫ scatter graph + best-fit line', '🧭 rose chart'][v.d]}</p>`) },
        { say: 'Paper 3 (Geographical Investigations) asks about planning an enquiry, sampling, equipment, presenting and evaluating data. Always ask: was the sample big enough? Fair? What would make the results more reliable?', ask: T('A fieldwork hypothesis should be…', ['a testable statement', 'a question with no answer', 'the conclusion'], 0, 'e.g. "Pedestrian counts fall with distance from the CBD."') }
      ], ['Choosing, drawing and interpreting graphs (including hydrographs, pyramids, climate graphs, scatter graphs).', 'Images, satellite photos and GIS (benefits, limitations).', 'Investigation cycle: hypothesis, methods, sampling, presentation, analysis, conclusion, evaluation.'], ['geSkills'])
    ] });
})();
